function formatClock(d) {
  var h = d.getHours();
  return (h % 12 || 12) + ':' + ('0' + d.getMinutes()).slice(-2);
}

let errors = 0;
for (let h = 0; h < 24; h++) {
  for (let m = 0; m < 60; m++) {
    const d = new Date(2026, 0, 1, h, m, 0);
    const formatted = formatClock(d);
    if (!/^(1[0-2]|[1-9]):[0-5][0-9]$/.test(formatted)) {
      console.error('Invalid clock format:', h, m, formatted);
      errors++;
    }
  }
}
console.log('Tested 1440 minute steps. Errors:', errors);
if (errors === 0) console.log('CLOCK FORMATTING PASS: 100% strictly valid 12-hour format');
